// 1. AUTO-RILEVAMENTO STRUTTURA DATI
let memosList = [];
const firstItem = $input.first().json;

if (firstItem.memos && Array.isArray(firstItem.memos)) {
  memosList = firstItem.memos;
} else {
  memosList = $input.all().map(item => item.json);
}

const chunks = [];

// 2. CHUNKING (800 char, overlap 100)
for (const memo of memosList) {
  const text = memo.content || '';
  const memoId = memo.name ? memo.name.split('/')[1] : (memo.id || 'unknown');
  const author = typeof memo.creator === 'string' ? memo.creator : ((memo.creator && memo.creator.nickname) || 'admin');
  const createdAt = memo.createTime || new Date().toISOString();
  const tags = memo.tags || [];

  if (!text || !text.trim()) continue;

  const chunkSize = 800;
  const overlap = 100;
  let index = 0;

  for (let i = 0; i < text.length; i += (chunkSize - overlap)) {
    const chunkText = text.substring(i, i + chunkSize);
    chunks.push({
      json: {
        memo_id: memoId,
        author: author,
        created_at: createdAt,
        chunk_index: index,
        text_content: chunkText.trim(),
        source_reference: 'memos://' + memoId,
        tags: tags,
        bionic_body: {
          model: 'text-embedding-bge-m3',
          input: chunkText.trim()
        }
      }
    });
    index++;
  }
}

return chunks;

// MERGE: ricongiunge embedding (risposta Bionic) con i campi originali del chunk
// Risolve il bug "campi persi dopo Bionic Embed"
const chunks = $('Code: Filter & Chunk').all();
const items = $input.all();

return items.map((item, i) => {
  const emb = (item.json.data && item.json.data[0]) ? item.json.data[0].embedding : null;
  const base = chunks[i] ? chunks[i].json : {};
  return {
    json: {
      ...base,
      embedding: emb
    }
  };
});

// === WF7 v2.0 === IDs FNV-1a (sandbox-safe) + Classificatore + Body nativo

// FNV-1a 64-bit deterministico -> intero uint64 valido per Qdrant
function fnv1a64(str) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  for (let i = 0; i < str.length; i++) {
    hash ^= BigInt(str.charCodeAt(i));
    hash = (hash * prime) & 0xFFFFFFFFFFFFFFFFn;
  }
  return Number(hash >> 11n);
}

// --- CLASSIFICATORE (tag reali Memos 08/10/2026) ---
const SELF_TAGS = new Set(['sys','sys/hardware','sys/sicurezza','sys/nodo','ops','ops/workflow','ops/backup','backup','ups','nut','storage','rete','ip','sicurezza','script','comandi','limiti','flussi','troubleshooting','always-on','architettura','themis','atlas','prometheus','hermes','s23','termux','android','trident','cluster','bionic','ai','ai/capacita','ai/agente','ai/mcp','llm','ollama','mcp','rag','embedding','memoria','axiom','cortex','nexus','sentinel','synapse','vanguard','n8n','workflow','automazione','wf1','wf2','wf3','wf4','qdrant','nextcloud','postgres','cloudflare','google-drive']);
const SELF_PREFIXES = ['sys/', 'ops/', 'ai/'];
const FORCE_SELF = new Set(['self']);
const FORCE_EPISODIC = new Set(['diario', 'foto', 'personale']);

const items = $input.all();
const out = [];

for (const item of items) {
  const emb = item.json.embedding;
  if (!emb || !Array.isArray(emb)) continue;

  // Estrai tag (dal campo tags o dal testo #tag)
  let tags = item.json.tags || [];
  if (!tags.length) {
    const m = (item.json.text_content || '').match(/#[a-zA-Z0-9_\/-]+/g) || [];
    tags = m.map(x => x.slice(1).toLowerCase());
  } else {
    tags = tags.map(t => String(t).toLowerCase().replace(/^#/, ''));
  }

  // Classificazione SELF / EPISODIC
  let docType = 'episodic_memory';
  let reason = 'default_episodic';
  if (tags.some(t => FORCE_SELF.has(t))) { docType = 'self_knowledge'; reason = 'override_#self'; }
  else if (tags.some(t => FORCE_EPISODIC.has(t))) { docType = 'episodic_memory'; reason = 'override_personale'; }
  else if (tags.some(t => SELF_TAGS.has(t) || SELF_PREFIXES.some(p => t.startsWith(p)))) { docType = 'self_knowledge'; reason = 'tag_sistema'; }
  else {
    const text = (item.json.text_content || '').toLowerCase();
    const kw = ['trident','themis','prometheus','atlas','qdrant','bionic','workflow','backup','cloudflare','nextcloud'];
    if (kw.some(k => text.includes(k))) { docType = 'self_knowledge'; reason = 'keyword_fallback'; }
  }

  // ID deterministico
  const idSource = `memos_${item.json.memo_id}_chunk${item.json.chunk_index}`;

  // Body Qdrant come OGGETTO NATIVO (niente espressioni n8n -> zero errori validazione)
  out.push({
    json: {
      document_type: docType,
      classification_reason: reason,
      body: {
        points: [{
          id: fnv1a64(idSource),
          vector: emb,
          payload: {
            source: 'memos',
            memo_id: item.json.memo_id,
            author: item.json.author,
            created_at: item.json.created_at,
            chunk_index: item.json.chunk_index,
            document_type: docType,
            classification_reason: reason,
            text_content: item.json.text_content,
            source_reference: item.json.source_reference
          }
        }]
      }
    }
  });
}

return out;

const items = $input.all();
console.log('✅ WF7 completato: ' + items.length + ' chunk indicizzati (SELF: ' + items.filter(i => i.json.document_type === 'self_knowledge').length + ' | EPISODIC: ' + items.filter(i => i.json.document_type === 'episodic_memory').length + ')');
return items;
